function normalizeMergeQueueEvent(event) {
	if (!event || typeof event !== 'object' || Array.isArray(event)) {
		return { valid: false, error: 'The request body must be an event object.' };
	}
	if (event.schema_version !== 1) {
		return { valid: false, error: 'schema_version must be 1.' };
	}
	if (
		event.repository !== 'n8n-io/n8n' ||
		typeof event.id !== 'string' ||
		!event.id.startsWith('n8n-io/n8n:') ||
		event.id.length > 512
	) {
		return { valid: false, error: 'A valid n8n-io/n8n repository and event ID are required.' };
	}
	if (typeof event.observed_at !== 'string' || !Number.isFinite(Date.parse(event.observed_at))) {
		return { valid: false, error: 'observed_at must be a valid timestamp.' };
	}
	if (
		!['merge_queue_group_created', 'merge_queue_run_failed', 'merge_queue_pr_enqueued', 'merge_queue_pr_dequeued'].includes(event.kind)
	) {
		return { valid: false, error: 'The event kind is not supported.' };
	}
	if (['merge_queue_group_created', 'merge_queue_run_failed'].includes(event.kind)) {
		if (typeof event.merge_group?.head_sha !== 'string' || !/^[a-f0-9]{40}$/i.test(event.merge_group.head_sha)) {
			return { valid: false, error: 'merge_group.head_sha must be a full commit SHA.' };
		}
	}
	if (event.kind === 'merge_queue_run_failed') {
		if (
			!Number.isSafeInteger(event.run?.id) || event.run.id < 1 ||
			!Number.isSafeInteger(event.run?.attempt) || event.run.attempt < 1 ||
			!Array.isArray(event.failed_jobs)
		) {
			return { valid: false, error: 'A source run ID, attempt, and failed_jobs array are required.' };
		}
	} else if (event.kind === 'merge_queue_group_created') {
		if (!Array.isArray(event.queue)) {
			return { valid: false, error: 'A queue snapshot array is required.' };
		}
	} else if (
		!Number.isSafeInteger(event.pr?.number) || event.pr.number < 1 ||
		typeof event.pr?.head_sha !== 'string' || !/^[a-f0-9]{40}$/i.test(event.pr.head_sha) ||
		!Array.isArray(event.queue)
	) {
		return { valid: false, error: 'A PR number, full PR head SHA, and queue snapshot array are required.' };
	}
	return { valid: true, event_id: event.id, event_json: JSON.stringify(event) };
}
const input = $input.first().json;
return [{ json: normalizeMergeQueueEvent(input.body ?? input) }];
